package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	var d string
	fmt.Scan(&d)
	n := len(d)

	dot := -1
	eIdx := -1
	for i := 0; i < n; i++ {
		if d[i] == '.' {
			dot = i
		}
		if d[i] == 'e' {
			eIdx = i
			break
		}
	}

	expStr := d[eIdx+1:]
	xb, _ := strconv.Atoi(expStr)

	var output strings.Builder

	isSpecial := (eIdx-dot == 2 && d[dot+1] == '0')

	for i := 0; i < n; i++ {
		if d[i] == '.' {
			if isSpecial {
				break
			}
			continue
		}
		if d[i] == 'e' {
			break
		}

		if i == dot+xb+1 {
			output.WriteByte('.')
		}
		output.WriteByte(d[i])
	}

	zero := xb - (eIdx - dot - 1)
	if isSpecial {
		zero = xb
	}

	for i := 0; i < zero; i++ {
		output.WriteByte('0')
	}

	fmt.Println(output.String())
}

